import React, { useState } from 'react';
import styled from 'styled-components';
import ExperimentAddPopup from "../components/ExperimentAdd";

const Container = styled.div`
  display: flex;
  justify-content: center;
  flex-direction: column;
  align-items: center;
`;

const Wrapper = styled.div`
  margin-top: 20px;
  width: 90%;
  flex-direction: column;
`;

const ButtonWrapper = styled.div`
  width: 100%;
  display: flex;
  justify-content: flex-end;
  margin-bottom: 20px;
`;

const Button = styled.button`
  padding: 12px 20px;
  font-size: 18px;
  background-color: #00aaff;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #0088cc;
  }
`;

const Title = styled.h1`
  text-align: center;
  font-size: 40px;
  color: #333;
  margin-bottom: 20px;
`;

const Table = styled.table`
  width: 100%;
  margin-top: 20px;
  border-collapse: collapse;
`;

const TableHeader = styled.th`
  padding: 12px;
  font-size: 18px;
  text-align: left;
  background-color: #f4f4f4;
  border: 1px solid #ddd;
`;

const TableRow = styled.tr`
  border: 1px solid #ddd;
`;

const TableData = styled.td`
  padding: 12px;
  font-size: 16px;
  border: 1px solid #ddd;
`;

const ViewDetailsWrapper = styled.div`
  display: flex;
  align-items: center;
  cursor: pointer;
  color: #00aaff;

  &:hover {
    color: #0088cc;
  }
`;

const ExperimentPage = () => {
  const [showModal, setShowModal] = useState(false);
  const [experiments, setExperiments] = useState([
    {
      id: 1,
      name: 'Thí nghiệm 1',
      code: 'TN001',
      experimenter: 'Người 1',
      creationTime: '2025-04-05 10:00',
    },
    {
      id: 2,
      name: 'Thí nghiệm 2',
      code: 'TN002',
      experimenter: 'Người 2',
      creationTime: '2025-04-06 11:00',
    },
    {
      id: 3,
      name: 'Thí nghiệm 3',
      code: 'TN003',
      experimenter: 'Người 3',
      creationTime: '2025-04-07 12:00',
    },
  ]);

  const openModal = () => setShowModal(true);
  const closeModal = () => setShowModal(false);

  const handleViewDetails = (experimentId) => {
    // Handle viewing details for the experiment
    alert(`Viewing details for experiment ID: ${experimentId}`);
  };

  return (
    <Container>
      <Wrapper>
        {/* Title */}
        <Title>Danh sách thí nghiệm</Title>

        {/* Button at the top-right */}
        <ButtonWrapper>
          <Button onClick={openModal}>Thêm thí nghiệm</Button>
        </ButtonWrapper>

        {/* Table to display experiments */}
        <Table>
          <thead>
            <tr>
              <TableHeader>STT</TableHeader>
              <TableHeader>Tên thí nghiệm</TableHeader>
              <TableHeader>Mã thí nghiệm</TableHeader>
              <TableHeader>Người thực hiện</TableHeader>
              <TableHeader>Thời gian tạo</TableHeader>
              <TableHeader>Chi tiết</TableHeader>
            </tr>
          </thead>
          <tbody>
            {experiments.map((experiment, index) => (
              <TableRow key={experiment.id}>
                <TableData>{index + 1}</TableData>
                <TableData>{experiment.name}</TableData>
                <TableData>{experiment.code}</TableData>
                <TableData>{experiment.experimenter}</TableData>
                <TableData>{experiment.creationTime}</TableData>
                <TableData>
                  <ViewDetailsWrapper onClick={() => handleViewDetails(experiment.id)}>
                    <span>🔍</span>
                    <span style={{ marginLeft: '8px' }}>Chi tiết</span>
                  </ViewDetailsWrapper>
                </TableData>
              </TableRow>
            ))}
          </tbody>
        </Table>

        <ExperimentAddPopup showModal={showModal} closeModal={closeModal} />
      </Wrapper>
    </Container>
  );
};

export default ExperimentPage;
